const discoveryModes=['mix','yandex','soundcloud','spotify'];let discoverySettings;
try{discoverySettings=JSON.parse(localStorage.getItem('soulroom.discovery'));if(!discoveryModes.includes(discoverySettings?.mode))throw Error()}catch{let mix;try{mix=JSON.parse(localStorage.getItem('soulroom.waveSources'))}catch{}discoverySettings={mode:'mix',mix:Array.isArray(mix)&&mix.length?mix:[...favoriteSources]}}
discoverySettings.mix=favoriteSources.filter(s=>Array.isArray(discoverySettings.mix)&&discoverySettings.mix.includes(s));if(!discoverySettings.mix.length)discoverySettings.mix=[...favoriteSources];
function discoverySources(){return discoverySettings.mode==='mix'?favoriteSources.filter(s=>discoverySettings.mix?.includes(s)):[discoverySettings.mode]}
waveSources=discoverySources();if(!waveSources.length)waveSources=[...favoriteSources];
const homeWaves=new Map(),homeRequests=new Map();let homeGeneration=0,homeTailObserver=null,tailAttempt='';
const homeMoodKeys=['mood:calm','activity:work','mood:sad','genre:ambient'];
let homePreviousArt={};try{homePreviousArt=JSON.parse(localStorage.getItem('soulroom.homeArt'))||{}}catch{}
const homeSessionOffset=(Number(localStorage.getItem('soulroom.homeOffset')||0)+1+Math.floor(Math.random()*3))%4;localStorage.setItem('soulroom.homeOffset',String(homeSessionOffset));
function moodStation(index){const patterns=[/спокой|релакс|calm|chill/i,/работ|фокус|концентр|focus/i,/ноч|меланх|night|sad/i,/ambient|эмбиент|релакс/i];return waveCategories.flatMap(c=>c.stations).find(s=>patterns[index].test(s.name))?.id||homeMoodKeys[index]}
function homeWaveKey(index){return moodStation(index)+'|'+discoverySources().join(',')}
function decorateHome(){if(page!=='home')return;document.querySelectorAll('.rooms [data-room]').forEach((card,index)=>{const batch=homeWaves.get(homeWaveKey(index)),img=card.querySelector('img'),small=card.querySelector('small'),badge=card.querySelector('.cover>span');if(batch?.items?.length){const cover=batch.cover||batch.items.find(t=>t.cover)?.cover;if(cover&&img)img.src=coverSource(cover);if(small)small.textContent=batch.items.slice(0,2).map(artist).join(' · ');if(badge)badge.textContent=batch.items.length+' ТРЕКОВ / '+discoverySources().map(s=>serviceNames[s]).join(' + ')}else{if(img)img.src=image((index+homeSessionOffset)%4);if(small)small.textContent=backend?'Подбираем музыку под тебя…':'Подключи источники для своей волны';if(badge)badge.textContent='ВОЛНА / '+discoverySources().map(s=>serviceNames[s]).join(' + ')}});const hero=$('.hero');if(hero){const b=hero.querySelector('[data-room]');if(b){b.removeAttribute('data-room');b.id='chooseMood';b.innerHTML=playerIcon('play')+'<span>Включить</span>'}const batch=homeWaves.get(homeWaveKey(0));hero.style.backgroundImage=`linear-gradient(90deg,#0b180ce8,#0b180c30),url("${coverSource(batch?.cover,image(homeSessionOffset))}")`}}
async function loadHomeWave(index,version=homeGeneration){const key=homeWaveKey(index);if(!backend)return;if(homeRequests.has(key))return homeRequests.get(key).promise;const token={};homeRequests.set(key,token);const promise=(async()=>{try{for(let attempt=0;attempt<5;attempt++){if(version!==homeGeneration)return;const query=new URLSearchParams({limit:'6',station:moodStation(index),sources:discoverySources().join(','),quick:'1'});const d=await api('wave?'+query);if(version!==homeGeneration)return;const items=Array.isArray(d.items)?d.items:[];if(items.length){const covers=items.map(t=>t.cover).filter(Boolean),different=covers.filter(c=>c!==homePreviousArt[index]),pool=different.length?different:covers,cover=pool[Math.floor(Math.random()*pool.length)];homeWaves.set(key,{...d,items,cover});if(cover){homePreviousArt[index]=cover;localStorage.setItem('soulroom.homeArt',JSON.stringify(homePreviousArt))}decorateHome();return}if(!d.warming)break;await new Promise(r=>setTimeout(r,2200))}}catch{}finally{if(homeRequests.get(key)===token)homeRequests.delete(key)}})();token.promise=promise;return promise}
async function loadHomeWaves(){if(!backend||page!=='home')return;const version=homeGeneration;await loadWaveStations();for(let i=0;i<4&&version===homeGeneration;i+=2)await Promise.all([loadHomeWave(i,version),loadHomeWave(i+1,version)])}
async function openMoodWave(mood){const index=Math.max(0,rooms.findIndex(r=>r[0]===mood));await loadWaveStations();const station=moodStation(index),batch=homeWaves.get(homeWaveKey(index));waveSources=discoverySources();if(batch?.items?.length){waveController?.abort();waveGeneration++;waveLoading=false;wavePending=null;waveStation=station;waveItems=[...batch.items];waveItems.forEach(t=>waveBatches.set(t.id,batch.batchId||null));waveEngine=batch.engine||'';waveMessage='Подборка из твоих выбранных источников';waveActive=false;localStorage.setItem('soulroom.waveStation',station);go('wave')}else resetWaveStation(station);tailAttempt=''}
function persistDiscovery(){localStorage.setItem('soulroom.discovery',JSON.stringify(discoverySettings));waveSources=discoverySources();localStorage.setItem('soulroom.waveSources',JSON.stringify(waveSources));waveController?.abort();waveGeneration++;waveLoading=false;wavePending=null;waveItems=[];waveMessage='';homeGeneration++;homeWaves.clear();homeRequests.clear();tailAttempt='';if(backend)api('settings',{method:'POST',body:JSON.stringify({wave:{sources:waveSources,defaultSource:discoverySettings.mode}})}).catch(()=>{});if(page==='home'){decorateHome();loadHomeWaves()}if(page==='wave')loadWave({fresh:true})}
const connectionsBeforeDiscovery=connectionsScreen;connectionsScreen=function(){const html=connectionsBeforeDiscovery();return `<section class="settings-card discovery-settings"><div><span class="eyebrow">ТВОЯ ВОЛНА</span><h3>Откуда подбирать музыку</h3><p>Общий выбор для главной страницы, настроений и волны.</p></div><label>Источник по умолчанию<select id="discoveryMode" aria-label="Источник рекомендаций">${discoveryModes.map(s=>`<option value="${s}" ${discoverySettings.mode===s?'selected':''}>${s==='mix'?'Смешивать выбранные сервисы':serviceNames[s]}</option>`).join('')}</select></label><div class="source-toggles ${discoverySettings.mode==='mix'?'':'hidden'}">${favoriteSources.map(s=>`<label><input type="checkbox" data-discovery-source="${s}" ${discoverySettings.mix?.includes(s)?'checked':''}>${serviceNames[s]}</label>`).join('')}</div></section>`+html};
document.addEventListener('change',e=>{if(e.target.id==='discoveryMode'){discoverySettings.mode=e.target.value;persistDiscovery();render()}if(e.target.dataset.discoverySource){const next=[...document.querySelectorAll('[data-discovery-source]:checked')].map(x=>x.dataset.discoverySource);if(!next.length){e.target.checked=true;toast('Выбери хотя бы один сервис');return}discoverySettings.mix=next;persistDiscovery()}if(e.target.dataset.waveSource){discoverySettings={mode:'mix',mix:[...waveSources]};localStorage.setItem('soulroom.discovery',JSON.stringify(discoverySettings));homeGeneration++;homeWaves.clear();tailAttempt=''}});
const moodPicker=document.createElement('dialog');moodPicker.className='quick-dialog mood-picker';moodPicker.setAttribute('aria-label','Настроение и жанр');document.body.append(moodPicker);
let pickerCategory='genre',pickerFromWave=false;
function stationCategories(){
 const cats=waveCategories.length?waveCategories:waveFallbackStations;
 return cats.filter(c=>c.type!=='personal'&&c.stations?.length).sort((a,b)=>Number(b.type==='genre')-Number(a.type==='genre'));
}
function refreshStationList(){
 const list=moodPicker.querySelector('.station-list');if(!list)return;
 const query=moodPicker.querySelector('#stationQuery').value.trim().toLocaleLowerCase('ru');
 const entries=stationCategories().filter(c=>query||c.type===pickerCategory).flatMap(c=>c.stations);
 const unique=[...new Map(entries.map(st=>[st.id,st])).values()].filter(st=>st.name.toLocaleLowerCase('ru').includes(query)).sort((a,b)=>a.name.localeCompare(b.name,'ru'));
 list.innerHTML=unique.map(st=>'<button class="station-choice" data-pick-station="'+esc(st.id)+'" aria-pressed="'+(waveStation===st.id)+'">'+esc(st.name)+(waveStation===st.id?' ✓':'')+'</button>').join('')||'<p>Совпадений нет</p>';
 for(const button of moodPicker.querySelectorAll('[data-station-tab]'))button.setAttribute('aria-pressed',String(button.dataset.stationTab===pickerCategory&&!query));
}
function showMoodPicker(fromWave=false){
 pickerFromWave=fromWave;
 const cats=stationCategories();
 pickerCategory=cats.find(c=>c.stations.some(st=>st.id===waveStation))?.type||cats[0]?.type;
 moodPicker.innerHTML='<div class="quick-title"><strong>'+ (fromWave?'Настроить волну':'Как ты сейчас?')+'</strong><button id="closeMoodPicker" aria-label="Закрыть">×</button></div>'+
 (!fromWave?'<div class="mood-picks">'+rooms.map((r,i)=>'<button data-pick-mood="'+i+'"><span>'+esc(r[0])+'</span><small>'+esc(r[1])+'</small></button>').join('')+'</div>':'')+
 '<button class="personal-station" data-pick-station="user:onyourwave">'+playerIcon('play')+' Для меня · Моя волна</button>'+
 '<input type="search" id="stationQuery" aria-label="Поиск станции" placeholder="Найти жанр или настроение">'+
 '<div class="station-tabs">'+cats.map(c=>'<button data-station-tab="'+esc(c.type)+'">'+esc(c.label)+'</button>').join('')+'</div><div class="station-list"></div>';
 refreshStationList();if(!moodPicker.open)moodPicker.showModal();
}
moodPicker.addEventListener('input',e=>{if(e.target.id==='stationQuery')refreshStationList()});
moodPicker.addEventListener('click',e=>{const b=e.target.closest('[data-station-tab]');if(b){pickerCategory=b.dataset.stationTab;$('#stationQuery').value='';refreshStationList()}});

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='chooseMood'||b.id==='chooseStation'){showMoodPicker(b.id==='chooseStation');loadWaveStations().then(()=>{if(moodPicker.open&&!$('#stationQuery').value&&stationCategories().length!==moodPicker.querySelectorAll('[data-station-tab]').length)showMoodPicker(pickerFromWave);else if(moodPicker.open)refreshStationList()})}if(b.id==='closeMoodPicker')moodPicker.close();if(b.dataset.pickMood!==undefined){moodPicker.close();openMoodWave(rooms[+b.dataset.pickMood][0])}if(b.dataset.pickStation){moodPicker.close();if(!pickerFromWave)waveSources=discoverySources();tailAttempt='';resetWaveStation(b.dataset.pickStation)}if(b.id==='refreshWave')tailAttempt=''});moodPicker.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation()});
function observeWaveTail(){homeTailObserver?.disconnect();if(page!=='wave'||!waveItems.length)return;const sentinel=$('#waveSentinel');if(!sentinel)return;homeTailObserver=new IntersectionObserver(entries=>{if(!entries.some(e=>e.isIntersecting)||waveLoading||page!=='wave')return;const key=waveStation+'|'+waveSources.join(',')+'|'+waveItems.length;if(tailAttempt===key)return;tailAttempt=key;loadWave({fresh:true,append:true})},{rootMargin:'500px'});homeTailObserver.observe(sentinel)}
const renderWaveBeforeDiscovery=renderWave;renderWave=function(){renderWaveBeforeDiscovery();observeWaveTail()};const renderBeforeDiscovery=render;render=function(){renderBeforeDiscovery();if(page==='home'){decorateHome();loadHomeWaves()}};
document.addEventListener('backend-ready',async()=>{if(!localStorage.getItem('soulroom.discovery'))try{const d=await api('settings');if(d.settings?.wave?.defaultSource){discoverySettings={mode:d.settings.wave.defaultSource,mix:d.settings.wave.sources};waveSources=discoverySources();localStorage.setItem('soulroom.discovery',JSON.stringify(discoverySettings))}}catch{}if(page==='home'){decorateHome();loadHomeWaves()}});if(page==='home'){decorateHome();loadHomeWaves()}
